value.value:
::view-transition-old(dialog),
::view-transition-new(dialog){
 animation-duration:0.5s;
}

::view-transition-old(dialog){
 animation-name:fade-out,scale-down;
}

::view-transition-new(dialog){
 animation-name:fade-in,scale-up;
}

@keyframes fade-out{
 to{
 opacity:0;
}
}

@keyframes fade-in{
 from{
 opacity:0;
}
}

@keyframes scale-down{
 from{
 transform:scale(1);
}
 to{
 transform:scale(0.95);
}
}

@keyframes scale-up{
 from{
 transform:scale(0.95);
}
 to{
 transform:scale(1);
}
}

