/**
 * @param {Args} args
 * @param {Ctx} ctx
 */
function OpenEyeDropper (args, ctx) {
  if (!window.EyeDropper) {
    return;
  }

  const eyeDropper = new EyeDropper();

  eyeDropper
    .open()
