        ctx.triggerActionEvent("change", result.sRGBHex)
    })
    .catch((e) => {
        ctx.triggerActionEvent("abort", e)
    });
}

SetVideoTime.handler:
/**
 * Sets the current time of a video element to a specific timestamp and starts playback
 * @param {Args} args
 * @param {Ctx} ctx
 */
function SetVideoTime(args, ctx) {
  const videoElement = ctx.root.getElementById(args.videoId);

  if (!videoElement) {
    ctx.triggerActionEvent('complete', { success: false, error: 'Video element not found' });
    return;
  }

  if (videoElement.tagName !== 'VIDEO') {
    ctx.triggerActionEvent('complete', { success: false, error: 'Element is not a video' });
    return;
  }

  try {
    videoElement.currentTime = args.timestamp;
    videoElement.play();
    ctx.triggerActionEvent('complete', { success: true, timestamp: args.timestamp });
  } catch (error) {
    ctx.triggerActionEvent('complete', { success: false, error: error.message });
  }
}

