function hexToHSLA(inputHex) {
  // Remove the # symbol from the beginning of the hex code
  let hexWithAlpha = inputHex.replace('#', '')
  if (hexWithAlpha.length === 3) {
    hexWithAlpha = hexWithAlpha.split("").map(k => `${k}${k}`).join("")
  }


  // Parse the hex code and alpha channel into separate RGBA components
  const r = parseInt(hexWithAlpha.substring(0, 2), 16) / 255
  const g = parseInt(hexWithAlpha.substring(2, 4), 16) / 255
  const b = parseInt(hexWithAlpha.substring(4, 6), 16) / 255
  const a = parseInt(hexWithAlpha.substring(6, 8), 16) / 255

  // Find the maximum and minimum values among R, G, and B components
  const max = Math.max(r, g, b)
  const min = Math.min(r, g, b)

  // Calculate the hue (H)
  let h = 0
  if (max !== min) {
    if (max === r) {
      h = ((g - b) / (max - min)) % 6
    } else if (max === g) {
      h = (b - r) / (max - min) + 2
    } else {
      h = (r - g) / (max - min) + 4
    }
  }
  h = Math.round(h * 600)/10
  if (h < 0) {
    h = 360 + h 
  }

  // Calculate the lightness (L)
  const l = (max + min) / 2

  // Calculate the saturation (S)
  let s = 0
  if (max !== min) {
    if (l < 0.5) {
      s = (max - min) / (max + min)
    } else {
      s = (max - min) / (2 - max - min)
    }
  }
  s = Math.round(s * 100)

  // Return the HSLA string
  return `hsl(${h}, ${s}%, ${l * 100}%, ${isNaN(a) ? 1 : a})`
}

hsla_to_hex.handler:
function hsla_to_hex(args) {
  // Extract the HSL values
  const [h, s, l, a] = args.hslaColor.match(/\d*\.?\d+/g).map(Number);

  // Convert HSL to RGB
  const sFraction = s / 100;
  const lFraction = l / 100;

  const c = (1 - Math.abs(2 * lFraction - 1)) * sFraction;
  const x = c * (1 - Math.abs(((h / 60) % 2) - 1));
  const m = lFraction - c / 2;

  let rPrime, gPrime, bPrime;

  if (h >= 0 && h < 60) {
    rPrime = c;
    gPrime = x;
    bPrime = 0;
  } else if (h >= 60 && h < 120) {
    rPrime = x;
    gPrime = c;
    bPrime = 0;
  } else if (h >= 120 && h < 180) {
    rPrime = 0;
    gPrime = c;
    bPrime = x;
  } else if (h >= 180 && h < 240) {
    rPrime = 0;
    gPrime = x;
    bPrime = c;
  } else if (h >= 240 && h < 300) {
    rPrime = x;
    gPrime = 0;
    bPrime = c;
  } else {
    rPrime = c;
    gPrime = 0;
    bPrime = x;
  }

  const r = Math.round((rPrime + m) * 255);
  const g = Math.round((gPrime + m) * 255);
  const b = Math.round((bPrime + m) * 255);

  // Convert RGB to Hex
  const rgbToHex = (r, g, b, a = 1) => '#' +
    [r, g, b].map(x => x.toString(16).padStart(2, '0')).join('') +
    (a < 1 ? Math.round(a * 255).toString(16).padStart(2, '0') : '');

  return rgbToHex(r, g, b, a);
}

