const AudioContext = window.AudioContext || window.webkitAudioContext;

window._webMediaAudioContext =  window._webMediaAudioContext ?? new AudioContext()


window._webMediaAudioBuffers = window._webMediaAudioBuffers ?? new Map();

async function PlayAudio (args, ctx) {
    const urls = typeof args.url === "string" ? [args.url] : (args.url ?? []);

    const buffers = await Promise.all(urls.map(url => getBuffer(url)))
    for (const buffer of buffers) {
         let source = window._webMediaAudioContext.createBufferSource();
        source.buffer = buffer;
        source.connect(window._webMediaAudioContext.destination);
            source.start();
    }   
}

async function getBuffer(url) {
        if (window._webMediaAudioBuffers.has(url)) {
            return window._webMediaAudioBuffers.get(url)
        }   
    const buffer = await fetch(url).then(r=> r.arrayBuffer()).then(buffer => window._webMediaAudioContext.decodeAudioData(buffer))
    window._webMediaAudioBuffers.set(url, buffer)
    return buffer

}

