const prepareEvent = (e) => {
    const oldIndex = e.oldIndex;
    const newIndex = e.newIndex;
    const fromElement = e.from;
    const toElement = e.to;
    const from = e.from?.dataset?.dndListId;
    const to = e.to?.dataset?.dndListId;
    const oldDraggableIndex = e.oldDraggableIndex;
    const newDraggableIndex = e.newDraggableIndex;

    return {
        oldIndex,
        newIndex,
        fromElement,
        toElement,
        from,
        to,
        oldDraggableIndex,
        newDraggableIndex,
        rawEvent: e,
    };
};

function addSortable(args, ctx) {

    const init = async () => {
        const { element, config, id } = args;

        if (!element) return

        try {
            await import(
                "https://cdn.jsdelivr.net/npm/sortablejs@1.15.6/Sortable.min.js"
            );

            // Events

            const onStart = (e) => {
                const oldIndex = e.oldIndex;
                const itemId = e?.item?.id;

                ctx.triggerActionEvent("On start", {
                    oldIndex,
                    itemId,
                    rawEvent: e,
                });
            };

            const onEnd = (e) => {
                ctx.triggerActionEvent("On end", prepareEvent(e));
            };

            const onAdd = (e) => {
                ctx.triggerActionEvent("On add", prepareEvent(e));
            };

            const onUpdate = (e) => {
                ctx.triggerActionEvent("On update", prepareEvent(e));
            };

            const onSort = (e) => {
                ctx.triggerActionEvent("On sort", prepareEvent(e));
            };

            const onRemove = (e) => {
                ctx.triggerActionEvent("On remove", prepareEvent(e));
            };

            const onFilter = (e) => {
                const item = e.tiem;

                ctx.triggerActionEvent("On filter", {
                    item,
                    rawEvent: e,
                });
            };

            const onMove = (e, originalEvent) => {
                const dragged = e.dragged;
                const draggedRect = e.draggedRect;
                const related = e.related;
                const relatedRect = e.relatedRect;
                const willInsertAfter = e.willInsertAfter;

                ctx.triggerActionEvent("On move", {
                    dragged,
                    draggedRect,
                    related,
                    relatedRect,
                    willInsertAfter,
                    rawEvent: e,
                    originalEvent,
                });
            };

            const onClone = (e) => {
                var originalElement = e.item;
                var cloneElement = e.clone;

                ctx.triggerActionEvent("On clone", {
                    originalElement,
                    cloneElement,
                    rawEvent: e,
                });
            };

            const onChange = (e) => {
                ctx.triggerActionEvent("On change", prepareEvent(e));
            };

            const sortable = new Sortable(element, {
                ...config,
                onStart,
                onEnd,
                onAdd,
                onRemove,
                onUpdate,
                onSort,
                onFilter,
                onMove,
                onClone,
                onChange,
            });

            if (id) {
                window[id] = sortable
            }

            ctx.triggerActionEvent("On init", { instance: sortable });

            return () => {
                sortable.destroy()
            }
        } catch (error) {
            console.error("Failed to load sortable js", error);
        }
    };

    init();
}

