function registerClassObserver(args, ctx) {
    const MAX_INIT_RETRIES = 50;
    const RETRY_TIMEOUT = 100;

    const { id, instance } = args;

    // Function that is called when the observer fires
    const observerCallback = (mutationsList, observer) => {
        for (const mutation of mutationsList) {
            if (
                mutation.type === "attributes" &&
                mutation.attributeName === "class"
            ) {
                ctx.triggerActionEvent("On class change", {
                    currentClasses: Array.from(mutation.target.classList),
                });
            }
        }
    };

    // Remove prior instances
    const currentObserver = window["observer-" + id];

    if (currentObserver) {
        currentObserver.disconnect();
    }

    // Register the observer
    const registerObserver = (currentTry = 0) => {
        const el = ctx.root.getElementById(id);

        if (!el) {
            if (currentTry < MAX_INIT_RETRIES) {
                setTimeout(() => registerObserver(currentTry + 1), RETRY_TIMEOUT);
            }
            return;
        }

        const observer = new MutationObserver(observerCallback);

        const config = {
            attributes: true,
            attributeFilter: ["class"],
        };

        observer.observe(el, config);

        window["observer-" + id] = observer;

        // Trigger init
        ctx.triggerActionEvent("On init", { instance: observer });
    };

    registerObserver(0);
}

