reorderedItems.handler:
/**
 * @param {Args} args
 * @param {Ctx} ctx
 */
function reorderedItems(args, ctx) {

    const { items, newIndex, newList, oldIndex, oldList } = args


    const newItems = items.map(item => {

        // Current item does not belong to an involved list
        if (item.status !== newList && item.status !== oldList) {
            return item
        }


        // Item was moved in the same list
        if (newList === oldList) {

            // Items was not moved
            if (newIndex === oldIndex) {
                return { ...item }
            }

            // The moved item will receive newIndex as order
            if (item.order === oldIndex) {
                return { ...item, order: newIndex }
            }

            // Item was moved upwards
            if (newIndex > oldIndex) {
                if (item.order <= newIndex && item.order > oldIndex) {
                    return { ...item, order: item.order - 1 }
                }
            }

            // Item was moved downwards
            if (newIndex < oldIndex) {
                if (item.order >= newIndex && item.order < oldIndex) {
                    return { ...item, order: item.order + 1 }
                }
            }
        }


        // Item was moved between lists
        if (newList !== oldList) {

            // The moved item will receive newIndex as order
            if (item.order === oldIndex && oldList === item.status) {
                return { ...item, order: newIndex, status: newList }
            }

            // Item is in the new list and must be moved upwards
            if (item.status === newList && item.order >= newIndex) {
                return { ...item, order: item.order + 1 }
            }

            // Item is in the old list and must be moved downwards
            if (item.status === oldList && item.order > oldIndex) {
                return { ...item, order: item.order - 1 }
            }
        }


        // Fallback (should not happen)
        return item
    })


    return newItems
}

