if (!customElements.get("lifecycle-util")) {
  class LifeCycleUtil extends HTMLElement {
    constructor() {
      super();
    }

    emitOnLoad() {
      const event = new CustomEvent("on-load", {
        bubbles: false,
        composed: true,
        detail: {},
      });
      this.dispatchEvent(event);
    }

    emitOnUnload() {
      const event = new CustomEvent("on-unload", {
        bubbles: false,
        composed: true,
        detail: {},
      });
      this.dispatchEvent(event);
    }

    // On load callback
    connectedCallback() {
      this.emitOnLoad();
    }

    // On unload callback
    disconnectedCallback() {
      this.emitOnUnload();
    }
  }

  customElements.define("lifecycle-util", LifeCycleUtil);
}

