/**
 * @param {Args} args
 * @param {Ctx} ctx
 */

window.__springs = window.__springs ?? {};
function spring (args, ctx) {
    //setup

    const stopThreshold = 0.5
    const spring = window.__springs[args.id] ?? {
        id:args.id
        }
    window.__springs[args.id] = spring;

    spring.stiffness = args.stiffness ?? spring.stiffness ?? 100;
    spring.damping = args.damping ?? spring.damping ?? 10;
    spring.mass = args.mass ?? spring.mass ?? 1;

    spring.value = spring.value ?? args.initialValue ?? 0
    spring.target = args.target
    spring.velocity = spring.velocity ?? 0;
    spring.lastTime = spring.lastTime ?? performance.now();

    if (spring.stopped === false) {
        return
    }
    spring.lastTime = performance.now()
        spring.stopped = false;

 function animate(currentTime) {
    const deltaTime = (currentTime - spring.lastTime) / 1000; // Convert to seconds
    spring.lastTime = currentTime;

    // Calculate spring force


    const displacement = spring.target - spring.value;
    const springForce = spring.stiffness * displacement;

    // Calculate damping force
    const dampingForce = spring.damping * spring.velocity;

    // Calculate acceleration (F = ma)
    const acceleration = (springForce - dampingForce) / spring.mass;

    // Update velocity and position

    spring.velocity += acceleration * deltaTime;
    spring.value += spring.velocity * deltaTime;


    if (Math.abs(spring.velocity) < stopThreshold && Math.abs(displacement) < stopThreshold) {
        spring.value = spring.target
        spring.stopped = true
    }


    // Call the callback with the current value
    ctx.triggerActionEvent("update", spring);
    if (spring.stopped) {
        ctx.triggerActionEvent("end", spring);
    }

    // Check if the animation should stop

    if (spring.stopped === false) {
    // Continue animation
    requestAnimationFrame(animate);
    }
  }

  requestAnimationFrame(animate);
}

