Angle.handler:
/**
 * Calculates the angle in degrees between two points relative to the horizontal axis
 * @param {Args} args - The input arguments containing point1 and point2
 * @param {Ctx} ctx
 * @returns {number} Angle in degrees
 */
function Angle(args, ctx) {
    const {x1, y1, x2, y2} = args

  if (!x1 || !y1 || !x2 || !y2) {
    return 0;
  }

  const deltaX = x2 - x1;
  const deltaY = y2 - y1;

  // Calculate angle in radians using Math.atan2
  const angleRadians = Math.atan2(deltaY, deltaX);

  // Convert radians to degrees and make the y axis 0
  const angleDegrees = angleRadians * (180 / Math.PI) -90;

  // Normalize angle to be between 0 and 360 degrees
  return (angleDegrees + 360 ) % 360;
}

