animateDemoValue.handler:
/**
 * @param {Args} args
 * @param {Ctx} ctx
 */
function animateDemoValue(args, ctx) {
  let start;

  function step(timestamp) {
    if (start === undefined) start = timestamp;
    const elapsed = timestamp - start;

    // Calculate progress as a value between 0 and 1
    const progress = Math.min(elapsed / 1000, 1);

    // Call the callback with the progress value
    ctx.triggerActionEvent("frame", Math.min(progress, 1));

    // If the animation is not yet complete, request another animation frame
    if (progress < 1) {
      ctx.triggerActionEvent("currentAnimationFrame", requestAnimationFrame(step));
    }
  }

  // Start the animation
  ctx.triggerActionEvent("currentAnimationFrame", requestAnimationFrame(step))
}

